challenge.verificationSource:
mod solution;

fn valid(input: &str, actual: &str, expected: &str) -> bool {
    if !input.contains("arranged=") { return actual == expected; }
    let parse = |text: &str| -> Option<Vec<i64>> { text.split(',').map(|x| x.trim().parse().ok()).collect() };
    let (Some(got), Some(mut want)) = (parse(actual), parse(expected)) else { return false; };
    let mut sorted = got.clone();
    sorted.sort();
    want.sort();
    let evens = got.iter().take_while(|x| *x % 2 == 0).count();
    sorted == want && got[evens..].iter().all(|x| x % 2 != 0)
}

fn main() {
    let cases = [
        ("[5, 2, 8, 1, 4]","3"),
        ("[1, 3]","0"),
        ("[1,2,3,4,5,6,7]","3"),
        ("[3,3,3,3,3,3,3]","0"),
        ("[8,7,6,5,4,3,2]","4"),
        ("arranged=[5,2,8,1,4]","2,8,4,1,5"),
        ("arranged=[1,2]","2,1"),
        ("  \n[5, 2, 8, 1, 4]\n  ","3"),
        ("\n[8,7,6,5,4,3,2]\n","4")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS predicate-partition");
}
